mapper.select:
SELECT tmp.id, tmp.tenant_id, tmp.user_id, tmp.conversation_id, tmp.content AS title, tmp.type, tmp.created_at
FROM (SELECT t.id,
t.tenant_id,
t.user_id,
t.conversation_id,
t.content,
t.type,
t.created_at,
ROW_NUMBER() OVER (PARTITION BY t.conversation_id ORDER BY t.created_at ) as rn
FROM sys_ai_chat_memory t
WHERE t.tenant_id = #{request.tenantId}
AND t.active = 1
AND t.chat_type = #{request.chatType}
AND t.user_id = #{request.userId}

    AND t.agent_code = #{request.agentCode}

) tmp
WHERE tmp.rn = 1

    AND tmp.id < #{request.lastId}

ORDER BY tmp.created_at DESC
